import{_ as e,o,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"GitHub Actions Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/action.md","filePath":"guide/action.md"}'),r={name:"guide/action.md"};function l(n,t,d,s,c,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="github-actions-deployment" tabindex="-1">GitHub Actions Deployment <a class="header-anchor" href="#github-actions-deployment" aria-label="Permalink to &quot;GitHub Actions Deployment&quot;">​</a></h1><p>Set up an automated CI/CD pipeline with GitHub Actions. Every push to the main branch automatically builds and deploys to Cloudflare Workers.</p><h2 id="step-1-create-cloudflare-api-token" tabindex="-1">Step 1: Create Cloudflare API Token <a class="header-anchor" href="#step-1-create-cloudflare-api-token" aria-label="Permalink to &quot;Step 1: Create Cloudflare API Token&quot;">​</a></h2><ol><li>Go to <a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">Cloudflare Dashboard → Profile → API Tokens</a></li><li>Click <strong>Create Token</strong></li><li>Choose the <strong>Edit Cloudflare Workers</strong> template</li><li>Configure permissions: <ul><li><strong>Account → Workers Scripts → Edit</strong></li><li><strong>Account → D1 → Edit</strong></li><li><strong>Account → KV → Edit</strong></li></ul></li><li>Click <strong>Continue to Summary</strong> → <strong>Create Token</strong></li><li><strong>Copy the token and save it securely</strong> — you won&#39;t see it again</li></ol><h2 id="step-2-copy-account-id" tabindex="-1">Step 2: Copy Account ID <a class="header-anchor" href="#step-2-copy-account-id" aria-label="Permalink to &quot;Step 2: Copy Account ID&quot;">​</a></h2><ol><li>In Cloudflare Dashboard, scroll to find your <strong>Account ID</strong> in the right sidebar</li><li>Copy it (it&#39;s a 32-character hex string)</li></ol><h2 id="step-3-fork-the-repository" tabindex="-1">Step 3: Fork the Repository <a class="header-anchor" href="#step-3-fork-the-repository" aria-label="Permalink to &quot;Step 3: Fork the Repository&quot;">​</a></h2><ol><li>Go to <a href="https://github.com/maillab/cloud-mail" target="_blank" rel="noreferrer">github.com/maillab/cloud-mail</a></li><li>Click <strong>Fork</strong></li></ol><h2 id="step-4-set-github-secrets" tabindex="-1">Step 4: Set GitHub Secrets <a class="header-anchor" href="#step-4-set-github-secrets" aria-label="Permalink to &quot;Step 4: Set GitHub Secrets&quot;">​</a></h2><p>Go to your forked repo → <strong>Settings → Secrets and variables → Actions → New repository secret</strong>.</p><p>Add these secrets:</p><table tabindex="0"><thead><tr><th>Secret Name</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td>✅</td><td>API token from Step 1</td></tr><tr><td><code>CLOUDFLARE_ACCOUNT_ID</code></td><td>✅</td><td>Account ID from Step 2</td></tr><tr><td><code>CUSTOM_DOMAIN</code></td><td>✅</td><td>Custom domain for Worker (e.g., <code>mail.example.com</code>)</td></tr><tr><td><code>DOMAIN</code></td><td>✅</td><td>Email domains as JSON array (e.g., <code>[&quot;example.com&quot;]</code>)</td></tr><tr><td><code>ADMIN</code></td><td>✅</td><td>Admin email (e.g., <code>admin@example.com</code>)</td></tr><tr><td><code>JWT_SECRET</code></td><td>✅</td><td>JWT secret (random string, no special chars)</td></tr><tr><td><code>NAME</code></td><td>❌</td><td>Worker project name (optional)</td></tr><tr><td><code>D1_DATABASE_ID</code></td><td>❌</td><td>D1 database ID (optional, auto-created if omitted)</td></tr><tr><td><code>KV_NAMESPACE_ID</code></td><td>❌</td><td>KV namespace ID (optional, auto-created if omitted)</td></tr></tbody></table><h2 id="step-5-run-the-workflow" tabindex="-1">Step 5: Run the Workflow <a class="header-anchor" href="#step-5-run-the-workflow" aria-label="Permalink to &quot;Step 5: Run the Workflow&quot;">​</a></h2><ol><li>Go to your forked repo → <strong>Actions</strong></li><li>Select the <strong>Deploy</strong> workflow on the left</li><li>Click <strong>Run workflow</strong> → <strong>Run workflow</strong></li></ol><h2 id="step-6-wait-for-deployment" tabindex="-1">Step 6: Wait for Deployment <a class="header-anchor" href="#step-6-wait-for-deployment" aria-label="Permalink to &quot;Step 6: Wait for Deployment&quot;">​</a></h2><p>The workflow will:</p><ul><li>Install dependencies</li><li>Build the Vue frontend</li><li>Deploy the Worker to Cloudflare</li><li>Create KV and D1 databases (if not already created)</li><li>Set environment variables and bindings</li></ul><p>Watch the workflow logs for progress.</p><h2 id="step-7-configure-email-routing" tabindex="-1">Step 7: Configure Email Routing <a class="header-anchor" href="#step-7-configure-email-routing" aria-label="Permalink to &quot;Step 7: Configure Email Routing&quot;">​</a></h2><ol><li>Go to <strong>Email → Email Routing</strong> in Cloudflare Dashboard</li><li>Enable Email Routing for your domain</li><li>Add a catch-all route pointing to your Worker</li></ol><h2 id="step-8-initialize-log-in" tabindex="-1">Step 8: Initialize &amp; Log In <a class="header-anchor" href="#step-8-initialize-log-in" aria-label="Permalink to &quot;Step 8: Initialize &amp; Log In&quot;">​</a></h2><ol><li>Open your custom domain in the browser</li><li>Visit <code>https://mail.example.com/api/init/&lt;your-jwt_secret&gt;</code> to initialize the DB</li><li>Register your admin account and sign in</li></ol><p>🎉 <strong>Done!</strong> Your Cloud Mail is live with automatic deployments.</p><h2 id="automatic-deploys" tabindex="-1">Automatic Deploys <a class="header-anchor" href="#automatic-deploys" aria-label="Permalink to &quot;Automatic Deploys&quot;">​</a></h2><p>From now on, every push to the <code>main</code> branch will automatically:</p><ol><li>Build the latest code</li><li>Deploy to Cloudflare Workers</li><li>Your service updates within seconds</li></ol>',26)])])}const m=e(r,[["render",l]]);export{h as __pageData,m as default};
